CREATE OR REPLACE FUNCTION credits_sandbox.guard_economy_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare e jsonb:=new.document->'economy'; previous jsonb:=old.document->'economy'; item record; d jsonb; config jsonb; registered jsonb; cnt int; fixture boolean;fixture_sport text;begin
 if previous is not null and e is null then raise exception 'Economy history cannot be removed';end if;
 if e is null then return new;end if;
 if e->>'id' is distinct from 'invited-nfl-test-v2' or new.document->'policy'->>'liveEnabled' is distinct from 'false'
 or new.document->'policy'->>'purchasedWithdrawable' is distinct from 'false' then raise exception 'Isolated nonwithdrawable economy required';end if;
 if previous is null and current_user='docked_beta_app' then raise exception 'Operator migration required';end if;
 if current_user='docked_beta_app' and previous->'enabled' is distinct from e->'enabled' then raise exception 'Operator activation required';end if;
 if current_user='docked_beta_app' and previous->'nbaTestAllocation' is distinct from e->'nbaTestAllocation' then raise exception 'Operator NBA fixture activation required';end if;
 if e ? 'nbaTestAllocation' and (e->'nbaTestAllocation'->>'scope' is distinct from 'isolated-fixtures-v1' or jsonb_typeof(e->'nbaTestAllocation'->'enabled') is distinct from 'boolean') then raise exception 'Isolated NBA fixture scope required';end if;
 if current_user='docked_beta_app' and previous->'fixtureTestAllocation' is distinct from e->'fixtureTestAllocation' then raise exception 'Operator fixture activation required';end if; if e->>'enabled'='true' and exists(select 1 from jsonb_object_keys(new.document->'commerce'->'orders') k where not coalesce(old.document->'commerce'->'orders','{}') ? k) then raise exception 'Legacy single-card purchases retired';end if;
 select document into config from credits_sandbox.rarity_configuration where version=e->>'rarityVersion';
 if config is null then raise exception 'Unknown rarity version';end if;
 for item in select key,value from jsonb_each(e->'players') loop
  if (item.value->>'sport' in ('basketball','afl','nrl') and (item.value->'synthetic'='true'::jsonb or credits_sandbox.is_roster_beta_player(item.value))) then
   select identity into registered from credits_sandbox.nba_fixture_players where id=item.key;
   if registered is distinct from item.value then raise exception 'Registered isolated player identity required';end if;
  else
   select identity into registered from credits_sandbox.permanent_players where id=item.key;
  end if;
  if registered is null or item.value->>'id'<>item.key or item.value->>'providerId'<>registered->>'providerId'
   or item.value->>'provider'<>registered->>'provider' or item.value->>'sport'<>registered->>'sport'
   or item.value->>'assetKind'<>registered->>'assetKind' then raise exception 'Permanent player identity mismatch';end if;
 end loop;
 for item in select key,value from jsonb_each(e->'products') loop
  select document into registered from credits_sandbox.pack_configuration where version=item.value->>'version';
  if registered is distinct from item.value or item.key<>item.value->>'id' or (item.value->>'cards')::int not in (1,3,9)
    or item.value->>'status'<>'TEST_ONLY' or (item.value->'weights'->>'ICON')::int<1
    or item.value->'weights' ? 'CORE' then raise exception 'Unregistered pack product';end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(e->'retiredTestInstances','{}')) loop
  if e->'instances' ? item.key or not exists(select 1 from nfl_roster.retired_test_cards a where a.card_id=item.key and a.allocation=item.value) then raise exception 'Unapproved retirement or resurrection';end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(previous->'retiredTestInstances','{}')) loop
  if e->'retiredTestInstances'->item.key is distinct from item.value then raise exception 'Retired scarcity cannot change';end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(previous->'instances','{}')) loop
  if e->'retiredTestInstances'->item.key=item.value and exists(select 1 from nfl_roster.retired_test_cards a where a.card_id=item.key and a.allocation=item.value and a.ownership=old.document->'commerce'->'cards'->item.key and a.history=old.document->'cards'->item.key) then
   if new.document->'commerce'->'cards' ? item.key or new.document->'cards' ? item.key then raise exception 'Retired ownership remains active';end if;
   continue;
  end if;
  if e->'instances'->item.key is distinct from item.value then raise exception 'Issued identity/serial is immutable';end if;
  if not(new.document->'commerce'->'cards' ? item.key) or not(new.document->'cards' ? item.key) then raise exception 'Ownership evidence required';end if;
  if exists(select 1 from jsonb_array_elements(old.document->'cards'->item.key->'history') with ordinality h(v,n) where new.document->'cards'->item.key->'history'->((h.n-1)::int) is distinct from h.v) then raise exception 'Ownership history append required';end if;
 end loop;
 for item in select key,value from jsonb_each(e->'definitions') loop
  if item.key<>((item.value->>'playerId')||':'||(item.value->>'rarity')) then raise exception 'Lifetime definition key';end if;
  select count(*) into cnt from jsonb_each(coalesce(e->'retiredTestInstances','{}') || (e->'instances')) x where x.value->>'definition'=item.key;
  if cnt<>(item.value->>'issued')::int then raise exception 'Issuance count mismatch';end if;
  if (e->'players'->(item.value->>'playerId')->>'sport' in ('basketball','afl','nrl') and (e->'players'->(item.value->>'playerId')->'synthetic'='true'::jsonb or credits_sandbox.is_roster_beta_player(e->'players'->(item.value->>'playerId')))) then
   if not exists(select 1 from credits_sandbox.nba_fixture_definitions where id=item.key) then insert into credits_sandbox.nba_fixture_definitions values(item.key,item.value->>'playerId',item.value->>'rarity',e->>'rarityVersion',(config->'rarities'->(item.value->>'rarity')->>'lifetimeCap')::int);end if;
  else
   insert into credits_sandbox.card_definitions values(item.key,item.value->>'playerId',item.value->>'rarity',e->>'rarityVersion',(config->'rarities'->(item.value->>'rarity')->>'lifetimeCap')::int) on conflict do nothing;
  end if;
 end loop;
 for item in select key,value from jsonb_each(e->'instances') order by (value->>'serial')::int loop
  fixture:=(e->'players'->(item.value->>'playerId')->>'sport' in ('basketball','afl','nrl') and (e->'players'->(item.value->>'playerId')->'synthetic'='true'::jsonb or credits_sandbox.is_roster_beta_player(e->'players'->(item.value->>'playerId'))));
  fixture_sport:=e->'players'->(item.value->>'playerId')->>'sport'; if fixture then
   if e->'packs'->(item.value->>'source')->'product'->>'sport' is distinct from fixture_sport then raise exception 'NBA fixture pack scope mismatch';end if;
   if previous->'instances'->item.key is distinct from item.value
    or old.document->'commerce'->'cards'->item.key is distinct from new.document->'commerce'->'cards'->item.key
    or old.document->'cards'->item.key is distinct from new.document->'cards'->item.key then
    if not credits_sandbox.fixture_allocation_enabled(e,fixture_sport) then raise exception 'NBA fixture allocation disabled';end if;
    perform credits_sandbox.assert_sport_fixture_member(new.document->'commerce'->'cards'->item.key->>'owner',fixture_sport);
    if old.document->'commerce'->'cards' ? item.key then perform credits_sandbox.assert_sport_fixture_member(old.document->'commerce'->'cards'->item.key->>'owner',fixture_sport);end if;
   end if;
   select document into registered from credits_sandbox.nba_fixture_instances where id=item.key::uuid;
  else
   select document into registered from credits_sandbox.card_instances where id=item.key::uuid;
  end if;
  if registered is null then
   fixture_sport:=e->'players'->(item.value->>'playerId')->>'sport'; if fixture then
    insert into credits_sandbox.nba_fixture_instances values(item.key::uuid,item.value->>'definition',(item.value->>'serial')::int,item.value);
   else
    insert into credits_sandbox.card_instances values(item.key::uuid,item.value->>'definition',(item.value->>'serial')::int,item.value);
   end if;
  elsif registered is distinct from item.value then raise exception 'Serial already issued';end if;
  if new.document->'commerce'->'cards'->item.key->>'tier' is distinct from item.value->>'rarity'
    or new.document->'commerce'->'cards'->item.key->>'owner' is null
    or new.document->'cards'->item.key->'history'->-1->>'to' is distinct from new.document->'commerce'->'cards'->item.key->>'owner'
    or not coalesce(e->'packs'->(item.value->>'source')->'cards','[]') ? item.key then raise exception 'Owned rarity required';end if;
 end loop;
 if ((select count(*) from credits_sandbox.card_instances)+(select count(*) from credits_sandbox.nba_fixture_instances))<>(select count(*) from jsonb_each(coalesce(e->'retiredTestInstances','{}') || (e->'instances'))) then raise exception 'Historical issuance missing';end if;
 for item in select key,value from jsonb_each(e->'packs') loop
  fixture_sport:=item.value->'product'->>'sport'; if fixture_sport in ('basketball','afl','nrl') and previous->'packs'->item.key is distinct from item.value then
   if not credits_sandbox.fixture_allocation_enabled(e,fixture_sport) then raise exception 'NBA fixture allocation disabled';end if;
   perform credits_sandbox.assert_sport_fixture_member(item.value->>'member',fixture_sport);
  end if;
  select document into registered from credits_sandbox.pack_configuration where version=item.value->'product'->>'version';
  if registered is null or registered is distinct from item.value->'product' then raise exception 'Unregistered pack receipt configuration';end if;
  if jsonb_array_length(item.value->'cards')<>(registered->>'cards')::int or
    (select count(distinct x) from jsonb_array_elements_text(item.value->'cards')x)<>(registered->>'cards')::int then raise exception 'Purchased card count and unique instances required';end if;
  for d in select value from jsonb_array_elements(item.value->'cards') loop
   if item.value->'product'->>'inventoryScope'='real-roster-beta-v1' and not credits_sandbox.is_roster_beta_player(e->'players'->(e->'instances'->(d#>>'{}')->>'playerId')) then raise exception 'Real-roster test pack requires verified isolated inventory';end if; if (coalesce(e->'retiredTestInstances','{}') || (e->'instances'))->(d#>>'{}')->>'source' is distinct from item.key then raise exception 'Pack allocation mismatch';end if;
   if fixture_sport in ('basketball','afl','nrl') and e->'players'->(e->'instances'->(d#>>'{}')->>'playerId')->>'sport' is distinct from fixture_sport then raise exception 'NBA fixture pack scope mismatch';end if;
  end loop;
  select document into registered from credits_sandbox.pack_receipts where id=item.key;
  if registered is null then insert into credits_sandbox.pack_receipts values(item.key,item.value-'openedAt');
  elsif registered is distinct from item.value-'openedAt' then raise exception 'Confirmed pack cannot be rerolled';end if;
  if previous->'packs'->item.key->>'openedAt' is not null and previous->'packs'->item.key->'openedAt' is distinct from item.value->'openedAt' then raise exception 'Opening receipt immutable';end if;
 end loop;
 if (select count(*) from credits_sandbox.pack_receipts)<>(select count(*) from jsonb_each(e->'packs')) then raise exception 'Pack history missing';end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION credits_sandbox.guard_pack_coupons()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c jsonb; r record; oldr jsonb; p jsonb; uses bigint; amount bigint; paid bigint;
begin
 if coalesce(new.document#>'{packCoupons,campaigns}','{}') is distinct from coalesce(old.document#>'{packCoupons,campaigns}','{}') then
  if not beta_private.active_member_session() or auth.jwt()->>'aal' is distinct from 'aal2'
   or not exists(select 1 from beta_private.roles where user_id=auth.uid() and role in ('owner','admin')) then raise exception 'Coupon administration requires staff MFA';end if;
  if coalesce(new.document#>'{packCoupons,redemptions}','{}') is distinct from coalesce(old.document#>'{packCoupons,redemptions}','{}') then raise exception 'Review campaign changes separately from purchases';end if;
  for r in select * from jsonb_each(coalesce(old.document#>'{packCoupons,campaigns}','{}')) loop
   if not coalesce(new.document#>'{packCoupons,campaigns}','{}') ? r.key then raise exception 'Coupon history cannot be deleted';end if;
  end loop;
 end if;
 for r in select * from jsonb_each(coalesce(old.document#>'{packCoupons,redemptions}','{}')) loop
  if new.document#>array['packCoupons','redemptions',r.key] is distinct from r.value then raise exception 'Completed coupon redemption is immutable';end if;
 end loop;
 for r in select * from jsonb_each(coalesce(new.document#>'{packCoupons,redemptions}','{}')) loop
  oldr:=old.document#>array['packCoupons','redemptions',r.key];
  if oldr is not null then continue;end if;
  c:=old.document#>array['packCoupons','campaigns',r.value#>>'{coupon,code}'];
  p:=new.document#>array['economy','packs',r.key];
  if c is null or r.value->'coupon' is distinct from c or c->>'status'<>'active'
    or (r.value->>'member')::uuid is distinct from auth.uid()
    or extract(epoch from statement_timestamp())*1000 < (c->>'startsAt')::bigint
    or extract(epoch from statement_timestamp())*1000 >= (c->>'expiresAt')::bigint
    or p is null or p->'pricing' is distinct from r.value
    or p->>'member' is distinct from r.value->>'member'
    or p#>>'{product,sport}' is distinct from c->>'sport'
    or not (c->'products' ? (p#>>'{product,id}')) then raise exception 'Coupon purchase eligibility changed';end if;
  select count(*) into uses from jsonb_each(new.document#>'{packCoupons,redemptions}') x where x.value#>>'{coupon,code}'=c->>'code';
  if uses>(c->>'totalLimit')::bigint then raise exception 'Coupon redemption limit reached';end if;
  select count(*) into uses from jsonb_each(new.document#>'{packCoupons,redemptions}') x where x.value#>>'{coupon,code}'=c->>'code' and x.value->>'member'=r.value->>'member';
  if uses>(c->>'accountLimit')::bigint then raise exception 'Account coupon limit reached';end if;
  if (c->>'firstPurchaseOnly')::boolean and exists(select 1 from jsonb_each(old.document->'entitlements') e join lateral jsonb_array_elements(old.document->'journal') j on j->>'id'=e.value->>'source' where e.value->>'member'=r.value->>'member' and right(j->>'id',5)='_pack') then raise exception 'First purchase restriction';end if;
  amount:=(p#>>'{product,priceCredits}')::bigint;
  paid:=amount-least(case when c->>'type'='percent' then floor((amount::numeric*(c->>'value')::numeric+50)/100)::bigint else (c->>'value')::bigint end,(c->>'maximumDiscount')::bigint,amount-case when (c->>'allowZero')::boolean then 0 else 1 end);
  if (r.value->>'original')::bigint<>amount or (r.value->>'charge')::bigint<>paid or (r.value->>'saving')::bigint<>amount-paid or paid<0 or amount-paid<=0
    or not exists(select 1 from jsonb_array_elements(new.document->'journal') j where j->>'id'=new.document#>>array['entitlements',r.key,'source'] and (select coalesce(sum((l->>'credits')::bigint),0) from jsonb_array_elements(j->'lines') l where l->>'account'='system:pack-revenue')=paid)
    then raise exception 'Coupon settlement does not reconcile';end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION credits_sandbox.guard_redemption()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb; pair record; prior jsonb;
begin
 p:=new.document->'redemption';
 if p is not null and p<>'null'::jsonb then
  if p->>'scope' is distinct from 'local-fixtures-only' or p->>'realDocumentsEnabled' is distinct from 'false' then raise exception 'Unapproved redemption boundary';end if;
  if p->>'enabled'='true' and current_database() not like 'docked_redemption_local_%' then raise exception 'Redemption restricted to dedicated local QA database';end if;
 end if;
 for pair in select key,value from jsonb_each(coalesce(new.document->'lots','{}')) loop
  if pair.value ? 'cashEligibility' and current_database() not like 'docked_redemption_local_%' then raise exception 'Test credits cannot acquire cash eligibility';end if;
  if tg_op='UPDATE' and old.document->'lots' ? pair.key and (old.document->'lots'->pair.key->'cashEligibility') is distinct from (pair.value->'cashEligibility') then raise exception 'Existing funding classification is immutable';end if;
 end loop;
 if tg_op='UPDATE' then
  for pair in select key,value from jsonb_each(coalesce(old.document->'withdrawals','{}')) where value ? 'manual' loop
   prior:=new.document->'withdrawals'->pair.key;
   if prior is null or (prior->'member') is distinct from (pair.value->'member') or (prior->'manual'->'requestedAt') is distinct from (pair.value->'manual'->'requestedAt') or (prior->'manual'->'policy') is distinct from (pair.value->'manual'->'policy') or (prior->'manual'->'destination') is distinct from (pair.value->'manual'->'destination') or (prior->'manual'->'rate') is distinct from (pair.value->'manual'->'rate') or (prior->'amount') is distinct from (pair.value->'amount') or (prior->'parts') is distinct from (pair.value->'parts') or (prior->'manual'->'audCents') is distinct from (pair.value->'manual'->'audCents') then raise exception 'Redemption financial snapshot is immutable';end if;
  end loop;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION credits_sandbox.marketplace_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record; prior jsonb; l jsonb; cid text;begin
 perform pg_advisory_xact_lock(71820342);
 if exists(select 1 from jsonb_each(new.document->'listings') x where x.value->>'status'='OPEN' group by x.value->>'card' having count(*)>1) then raise exception 'One active listing per card';end if;
 for item in select key,value from jsonb_each(old.document->'requests') loop
  if new.document->'requests'->item.key is distinct from item.value then raise exception 'Transaction identity and receipt immutable';end if;
 end loop;
 for item in select key,value from jsonb_each(new.document->'listings') loop
  l:=item.value;prior:=old.document->'listings'->item.key; if prior is distinct from l and exists(select 1 from credits_sandbox.nba_fixture_instances where id::text=l->>'card') and not credits_sandbox.fixture_trade_allowed(new.document,jsonb_build_array(l->>'card'),array[l->>'member']) then raise exception 'Fixture trading disabled or admission revoked';end if;
  if jsonb_typeof(l->'price') is distinct from 'number' or (l->>'price')::numeric not between 0 and 1000000000 or trunc((l->>'price')::numeric)<>(l->>'price')::numeric then raise exception 'Positive integer credit price required';end if;
  if coalesce(l->>'preference','sell') not in ('sell','swap','both') or ((coalesce(l->>'preference','sell')='swap') <> ((l->>'price')::numeric=0)) then raise exception 'Listing preference and price mismatch';end if;
  if l->>'status' is null or l->>'status' not in('OPEN','SOLD','CANCELLED') then raise exception 'Invalid listing status';end if;
  if prior is not null and ((prior-array['status','buyer','receipt','cancelledAt','price','revision','feePolicy']) is distinct from (l-array['status','buyer','receipt','cancelledAt','price','revision','feePolicy']) or (prior->>'status'<>'OPEN' and prior is distinct from l)) then raise exception 'Listing terms and closed history immutable';end if;
  if l->>'status'='OPEN' and (coalesce(l->>'preference','sell')<>'sell' or (l->>'price')::bigint<1) and not credits_sandbox.fixture_trade_allowed(new.document,jsonb_build_array(l->>'card'),array[l->>'member']) then raise exception 'Only fixed-price credit listings supported';end if;
  if prior is not null and prior->>'status'='OPEN' and l->>'status'<>'OPEN' and (prior->'price' is distinct from l->'price' or prior->'revision' is distinct from l->'revision' or prior->'feePolicy' is distinct from l->'feePolicy') then raise exception 'Closing listing terms immutable';end if;
  if prior is not null and prior->>'status'='OPEN' and l->>'status'='OPEN' and l is distinct from prior then
   if coalesce((l->>'revision')::int,0)<>coalesce((prior->>'revision')::int,0)+1 then raise exception 'Listing revision required';end if;
   if auth.uid() is not null and auth.uid()::text<>l->>'member' then raise exception 'Only the seller may edit this listing';end if;
   if l->>'feePolicy'<>'credit-sale-5pct-cap2000-v2' then raise exception 'Current fee policy required';end if;
  end if;
  if l->>'status'='OPEN' and (new.document#>>array['commerce','cards',l->>'card','owner'] is distinct from l->>'member' or new.document#>>array['cards',l->>'card','version'] is distinct from l->>'version') then raise exception 'Listing ownership/version required';end if;
  if prior is null then
   if l->>'feePolicy' is distinct from 'credit-sale-5pct-cap2000-v2' or l->>'revision' is distinct from '1' then raise exception 'Current fee policy and initial revision required';end if;
   if l->>'status'<>'OPEN' or new.document#>>array['commerce','cards',l->>'card','tier']='CORE' then raise exception 'Eligible limited test card required';end if;
   if sports_feed.card_entry_reserved((l->>'card')::uuid) then raise exception 'Card used by an unlocked submitted team';end if;
   if exists(select 1 from jsonb_each(new.document->'swaps') x where x.value->>'status'='OPEN' and (x.value->>'expires')::numeric>extract(epoch from clock_timestamp())*1000 and ((x.value->'give')||(x.value->'take')) ? (l->>'card')) then raise exception 'Card reserved by active swap';end if;
  end if;
  if l->>'status'='SOLD' and prior->>'status'='OPEN' then
   if l#>>'{receipt,feePolicy}' is distinct from 'credit-sale-5pct-cap2000-v2' then raise exception 'Recorded fee policy required';end if;
   if jsonb_typeof(l->'receipt') is distinct from 'object' or not (l->'receipt') ?& array['reference','at','price','fee','net'] or (l->'receipt'->>'price')::bigint<>(l->>'price')::bigint or (l->'receipt'->>'fee')::bigint<>least(2000,round((l->>'price')::numeric*0.05)) or (l->'receipt'->>'net')::bigint<>(l->>'price')::bigint-(l->'receipt'->>'fee')::bigint then raise exception 'Exact sale receipt required';end if;
   if new.document#>>array['commerce','cards',l->>'card','owner'] is distinct from l->>'buyer' or l->>'buyer'=l->>'member' then raise exception 'Sale ownership required';end if;
   if not exists(select 1 from credits_sandbox.journal j where j.id=l->'receipt'->>'reference') then raise exception 'Sale journal required';end if;
  end if;
 end loop;
 if exists(select 1 from jsonb_object_keys(old.document->'listings') k where not (new.document->'listings') ? k) then raise exception 'Listing history cannot be removed';end if;
 for item in select key,value from jsonb_each(new.document->'swaps') where value->>'status'='OPEN' and (value->>'expires')::numeric>extract(epoch from clock_timestamp())*1000 loop
  if old.document->'swaps'->item.key is null then
   for cid in select jsonb_array_elements_text((item.value->'give')||(item.value->'take')) loop
    if sports_feed.card_entry_reserved(cid::uuid) then raise exception 'Card used by an unlocked submitted team';end if;
   end loop;
  end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(new.document->'swaps','{}')) loop
  prior:=old.document->'swaps'->item.key;
  if (prior is null and item.value->>'status'='OPEN') or (prior->>'status'='OPEN' and item.value->>'status'='ACCEPTED') then if not credits_sandbox.fixture_trade_allowed(new.document,item.value->'give'||item.value->'take',array[item.value->>'member',item.value->>'other']) then raise exception 'New swaps and swap acceptance disabled';end if;end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(new.document->'privateCardOffers','{}')) loop
  prior:=old.document->'privateCardOffers'->item.key;
  if (prior is null and item.value->>'status'='OPEN') or (prior->>'status'='OPEN' and item.value->>'status'='ACCEPTED') then if not credits_sandbox.fixture_trade_allowed(new.document,jsonb_build_array(item.value->>'card')||coalesce((select jsonb_agg(x->>'id') from jsonb_array_elements(item.value->'offeredCards') x),'[]'),array[item.value->>'seller',item.value->>'buyer']) then raise exception 'Private offers disabled';end if;end if;
 end loop;
 return new;
end$function$

CREATE OR REPLACE FUNCTION credits_sandbox.private_offer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record; prior jsonb; o jsonb; offered jsonb; receipt jsonb;
begin
 for item in select key,value from jsonb_each(coalesce(old.document->'privateCardOffers','{}')) loop
  o:=new.document->'privateCardOffers'->item.key; prior:=item.value;
  if o is null or (o-array['status','closed','receipt','listing']) is distinct from (prior-array['status','closed','receipt','listing']) then raise exception 'Private offer terms immutable'; end if;
  if prior->>'status'<>'OPEN' and o is distinct from prior then raise exception 'Completed private offer immutable'; end if;
 end loop;
 for item in select key,value from jsonb_each(coalesce(new.document->'privateCardOffers','{}')) loop
  o:=item.value; prior:=old.document->'privateCardOffers'->item.key;
  if o->>'id' is distinct from item.key or o->>'buyer'=o->>'seller' or o->>'status' not in ('OPEN','ACCEPTED','DECLINED','CANCELLED','EXPIRED') then raise exception 'Invalid private offer'; end if;
  if prior is null and o->>'status'<>'OPEN' then raise exception 'Private offer must start open'; end if;
  if jsonb_typeof(o->'price') is distinct from 'number' or (o->>'price')::numeric not between 0 and 1000000000 or trunc((o->>'price')::numeric)<>(o->>'price')::numeric then raise exception 'Invalid credit component'; end if;
  offered:=coalesce(o->'offeredCards','[]');
  if jsonb_typeof(offered)<>'array' or jsonb_array_length(offered)>1 or ((o->>'price')::numeric=0 and jsonb_array_length(offered)=0) then raise exception 'One offered card supported'; end if;
  if o->>'status'='ACCEPTED' and prior->>'status'='OPEN' then
   if jsonb_array_length(offered)>0 then
    receipt:=new.document->'swaps'->(o->>'receipt');
    if receipt->>'status' is distinct from 'ACCEPTED' or receipt->>'member' is distinct from o->>'buyer' or receipt->>'other' is distinct from o->>'seller' or receipt->'take' is distinct from jsonb_build_array(o->>'card') or receipt->'give' is distinct from jsonb_build_array(offered->0->>'id') or coalesce(receipt->>'creditTopUp','0')<>o->>'price' then raise exception 'Offer exchange receipt mismatch'; end if;
   else
    receipt:=new.document->'listings'->(o->>'listing');
    if receipt->>'status' is distinct from 'SOLD' or receipt->>'privateOffer' is distinct from item.key or receipt->>'buyer' is distinct from o->>'buyer' or receipt->>'member' is distinct from o->>'seller' or receipt->>'card' is distinct from o->>'card' or receipt->'price' is distinct from o->'price' then raise exception 'Offer sale receipt mismatch'; end if;
   end if;
  end if;
 end loop;
 return new;
end $function$
